    IF to_regclass('lifecycle.final_settlements') IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = to_regclass('lifecycle.final_settlements') AND conname = 'ck_final_settlements_legal_basis_max_length__max_length') THEN
        IF EXISTS (SELECT 1 FROM lifecycle.final_settlements WHERE NOT ((char_length(legal_basis) <= 120))) THEN
            RAISE NOTICE 'ck_final_settlements_legal_basis_max_length__max_length not added: stored rows of lifecycle.final_settlements break it';
        ELSE
            ALTER TABLE lifecycle.final_settlements ADD CONSTRAINT ck_final_settlements_legal_basis_max_length__max_length CHECK ((char_length(legal_basis) <= 120));
        END IF;
    END IF;
EXCEPTION WHEN undefined_column THEN
    RAISE NOTICE 'ck_final_settlements_legal_basis_max_length__max_length not added: lifecycle.final_settlements lacks a column it reads';
END $$;

